import "./StatusMessage.css";

export interface StatusMessageProps {
  readonly text: string;
  readonly onDismiss: () => void;
}

export function StatusMessage({ text, onDismiss }: StatusMessageProps) {
  return (
    <div className="status-message">
      <p role="status" aria-live="polite" aria-atomic="true" className="status-message__text">
        {text}
      </p>
      <button type="button" className="status-message__dismiss" onClick={onDismiss}>
        Dismiss
      </button>
    </div>
  );
}
```

```css
.status-message {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.6rem 0.9rem;
  border: 1px solid var(--myelin);
  border-radius: 12px;
  background: var(--myelin-wash);
  color: var(--ink);
  font: inherit;
  font-size: clamp(0.875rem, 0.8rem + 0.3vw, 1rem);
  animation: status-message-in 200ms ease-out;
}

.status-message__text {
  flex: 1;
  margin: 0;
}

.status-message__dismiss {
  font: inherit;
  font-size: 0.875rem;
  color: var(--ink);
  background: transparent;
  border: 1px solid var(--ink);
  border-radius: 999px;
  padding: 0.25rem 0.75rem;
  cursor: pointer;
}

.status-message__dismiss:hover {
  background: var(--code-bg);
}

@keyframes status-message-in {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

:root[data-motion="reduce"] .status-message {
  animation: none;
}

@media (prefers-reduced-motion: reduce) {
  .status-message {
    animation: none;
  }
}
```

